/* From Uiverse.io by The-Best-Codes  - Tags: material design, animation, green, switch, checkbox, modern, css, css effect */
.__UIV_SCOPE__ .toggle-switch {
  display: inline-block;
  position: relative;
  width: 60px;
  height: 34px;
}

.__UIV_SCOPE__ .toggle-input {
  display: none;
}

.__UIV_SCOPE__ .toggle-label {
  position: absolute;
  top: 0;
  left: 0;
  width: 60px;
  height: 34px;
  background-color: #ccc;
  border-radius: 34px;
  cursor: pointer;
  transition: background-color 0.3s;
}

.__UIV_SCOPE__ .toggle-label:before {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 30px;
  height: 30px;
  background-color: #fff;
  border-radius: 50%;
  transition: transform 0.3s;
}

.__UIV_SCOPE__ .toggle-input:checked + .toggle-label {
  background-color: #4fbf26;
}

.__UIV_SCOPE__ .toggle-input:checked + .toggle-label:before {
  transform: translateX(26px);
}
